namespace SimplePZMapmaker.Core;
public sealed record SourceOutlinePoint(double Longitude,double Latitude);
/// <summary>Center-sample rasterization preserves source concavity and courtyard holes at game-tile resolution.</summary>
public static class ImportedBuildingGeometry {
 public static bool Apply(Building b,List<List<(double X,double Y)>> rings,out string reason){
  reason="";if(rings.Count==0||rings.Any(r=>r.Count<4||r[0]!=r[^1])){reason="Open or incomplete source footprint";return false;}
  var mask=new bool[b.Width*b.Height];var intersections=new List<double>();
  for(var y=0;y<b.Height;y++){intersections.Clear();var scan=b.Y+y+.5;foreach(var ring in rings)for(int i=0,j=ring.Count-1;i<ring.Count;j=i++)if((ring[i].Y>scan)!=(ring[j].Y>scan))intersections.Add(ring[i].X+(scan-ring[i].Y)*(ring[j].X-ring[i].X)/(ring[j].Y-ring[i].Y));intersections.Sort();for(var i=0;i+1<intersections.Count;i+=2){var first=Math.Clamp((int)Math.Ceiling(intersections[i]-b.X-.5),0,b.Width);var end=Math.Clamp((int)Math.Ceiling(intersections[i+1]-b.X-.5),0,b.Width);for(var x=first;x<end;x++)mask[y*b.Width+x]=true;}}
  var count=mask.Count(v=>v);if(count<BuildingDesigner.MinimumFootprint*BuildingDesigner.MinimumFootprint){reason="Source footprint too narrow at this scale";return false;}
  var start=Array.FindIndex(mask,v=>v);var queue=new Queue<int>();var visited=new HashSet<int>{start};queue.Enqueue(start);while(queue.TryDequeue(out var i)){var x=i%b.Width;var y=i/b.Width;foreach(var (dx,dy) in new[]{(1,0),(-1,0),(0,1),(0,-1)}){var xx=x+dx;var yy=y+dy;if(xx>=0&&yy>=0&&xx<b.Width&&yy<b.Height&&mask[yy*b.Width+xx]&&visited.Add(yy*b.Width+xx))queue.Enqueue(yy*b.Width+xx);}}
  if(visited.Count!=count){reason="Disconnected source footprint at this scale";return false;}
  var original=b.Design??throw new ArgumentException("A source footprint needs a generated interior.");var direction="n";var stair=-1;
  if(original.Floors.Count>1){foreach(var dir in new[]{"n","w"}){for(var y=0;y<b.Height&&stair<0;y++)for(var x=0;x<b.Width&&stair<0;x++){if(Enumerable.Range(0,5).All(i=>x+(dir=="w"?i:0)<b.Width&&y+(dir=="n"?i:0)<b.Height&&mask[(y+(dir=="n"?i:0))*b.Width+x+(dir=="w"?i:0)])){stair=y*b.Width+x;direction=dir;}}if(stair>=0)break;}if(stair<0){reason="Source footprint cannot fit connected stairs at this scale";return false;}}
  var draft=NeighborhoodPlanner.Copy(original);b.Design=draft;draft.Shape="custom";
  for(var z=0;z<draft.Floors.Count;z++){var f=draft.Floors[z];var cells=f.Cells.ToCharArray();for(var i=0;i<mask.Length;i++)if(!mask[i])cells[i]='.';f.Objects.Clear();f.FloorTile=null;f.FloorTiles.Clear();f.StaticModels.Clear();if(stair>=0){for(var i=0;i<5;i++)cells[(stair/b.Width+(direction=="n"?i:0))*b.Width+stair%b.Width+(direction=="w"?i:0)]='0';if(z<draft.Floors.Count-1)f.Objects.Add(new(){X=stair%b.Width,Y=stair/b.Width,Kind="stairs",Direction=direction});}f.Cells=new(cells);f.Edges=BuildingDesigner.AutoEdges(b,f,z+draft.MinLevel);}
  try{BuildingDesigner.Validate(b);for(var z=0;z<draft.Floors.Count;z++)BuildingDesigner.Furnish(b,z,new Random(unchecked(draft.Variant+z*1009)));BuildingDesigner.Validate(b);b.FootprintOrigin="source-grid";return true;}catch(ArgumentException){b.Design=original;reason="Source footprint cannot support an accessible generated interior";return false;}
 }
 public static List<List<SourceOutlinePoint>> Capture(List<List<(double X,double Y)>> rings,out bool simplified){simplified=rings.Any(r=>r.Count>512)||rings.Count>16;return rings.Take(16).Select(r=>{if(r.Count<=512)return r.Select(p=>new SourceOutlinePoint(p.X,p.Y)).ToList();var result=Enumerable.Range(0,511).Select(i=>r[(int)((long)i*(r.Count-1)/510)]).Select(p=>new SourceOutlinePoint(p.X,p.Y)).ToList();result.Add(result[0]);return result;}).ToList();}
 public static void Validate(Building b){if(b.FootprintOrigin is not("authored" or "source-grid" or "manual-source-edit")||b.SourceOutline is null||b.SourceOutline.Count>16||b.SourceOutline.Any(r=>r is null||r.Count is <4 or >512||r.Any(p=>p is null||!double.IsFinite(p.Longitude)||!double.IsFinite(p.Latitude)||p.Longitude is < -180 or >180||p.Latitude is < -85 or >85)||r[0]!=r[^1]))throw new ArgumentException("Invalid building source footprint metadata.");}
}
